import React from "react";
import "./portfolio.css";
import IMG1 from "../../assets/keypoints.jpg";
import IMG2 from "../../assets/devcalisthenicsapp.png";
import IMG3 from "../../assets/photographyport.png";
import IMG4 from "../../assets/dbsql.png";
import IMG5 from "../../assets/bcanalysis.png";
import IMG6 from "../../assets/iss.png";
import MalariaPDF from "../../assets/Malaria Classifier.pdf";
import UniPDF from "../../assets/University Database Report.pdf"
import BCPDF from "../../assets/Breast Cancer Analysis Report.pdf"

//THIS IS TO MAP
const data = [
  {
    id: 3,
    image: IMG5,
    title: "Data-Driven Insights for Early Breast Cancer Diagnosis",
    github: "https://github.com/Juan-Carlos-D/breast-cancer-data-analysis",
    demo: BCPDF
  },
  {
    id: 1,
    image: IMG1,
    title: "Scalable Machine Learning Model for Malaria Diagnosis",
    github: "https://github.com/Juan-Carlos-D/Malaria-Classifier",
    demo: MalariaPDF
  },
  {
    id: 2,
    image: IMG4,
    title: "Comprehensive Academic Program Monitoring & Evaluation System",
    github: "https://github.com/Juan-Carlos-D/University-Database-Management",
    demo: UniPDF
  },
  {
    id: 4,
    image: IMG2,
    title: "NovaFit: Fullstack Fitness App with AI Assistance",
    github: "https://github.com/Juan-Carlos-D/DevCalisthenics-App",
    demo: "https://juan-carlos-d.github.io/DevCalisthenics/"
  },
  {
    id: 5,
    image: IMG3,
    title: "Interactive & Dynamic Photography Portfolio Showcase",
    github: "https://github.com/Juan-Carlos-D/photographyport?search=1",
    demo: "https://juan-carlos-d.github.io/photographyport/"
  },
  {
    id: 6,
    image: IMG6,
    title: "Real-Time International Space Station Positioning & Monitoring Tool",
    github: "https://github.com/Juan-Carlos-D/iss-tracker",
    demo: "https://juan-carlos-d.github.io/iss-tracker/"
  }
];



const Portfolio = () => {
  return (
    <section id="portfolio">
      <h5>My Recent Work</h5>
      <h2>Portfolio</h2>

      <div className="container portfolio__container">
        {data.map(({ id, image, title, github, demo }) => {
          return (
            <article key={id} className="portfolio__item">
              <div className="portfolio__item-image">
                <img src={image} alt={title} />
              </div>
              <h3>{title}</h3>
              <div className="portfolio__item-cta">
                <a
                  href={github}
                  className="btn"
                  target="_blank"
                  rel="noreferrer"
                >
                  Github
                </a>
                {id === 1 || id === 2 || id === 3 ? (
                  <a
                    href={demo}
                    className="btn btn-primary"
                    target="_blank"
                    rel="noreferrer"
                  >
                    View Report
                  </a>
                ) : (
                  <a
                    href={demo}
                    className="btn btn-primary"
                    target="_blank"
                    rel="noreferrer"
                  >
                    Live Demo
                  </a>
                )}
              </div>
            </article>
          );
        })}
      </div>
    </section>
  );
};


export default Portfolio;